solution:
"""Check Whether the Kth Bit Is Set — mask with 1 << (k - 1).

Time: O(1)   Space: O(1)
"""


class Solution:
    def isKthBitSet(self, n: int, k: int) -> bool:
        return bool(n & (1 << (k - 1)))
